node_ctr=0; t0=time.time()
@lru_cache(None)
def solve_pack(used, counts):
    global node_ctr
    node_ctr += 1
    if not any(counts):
        rem=fullmask4 ^ used
        if rem.bit_count()==4:
            return ()
        return None
    best_i=None; best_opts=None
    for i,n in enumerate(counts):
        if n:
            opts=[p for p in plists[i] if p[0]&used==0]
            if not opts:
                return None
            if best_opts is None or len(opts)<len(best_opts):
                best_i=i; best_opts=opts
    # Favor placements that cover cells constrained for remaining pieces; order geometry fixed
    newcounts=list(counts); newcounts[best_i]-=1; newcounts=tuple(newcounts)
    for p in best_opts:
        res=solve_pack(used|p[0],newcounts)
        if res is not None:
            return ((shape_types[best_i],p),)+res
    return None
